-- Sean, 2026-11-10: "change the survey wording to Founding Member is free". The three Wednesday follow-ups no longer mention a survey.
-- Applied 2026-11-10 (the stored text had been edited after 20261108_founding_cohort_1_wednesday_followups.sql; these match the stored text).
update ve_outreach_campaign_emails set body = replace(body, 'If you haven''t yet, joining takes about two minutes.', 'If you haven''t yet, becoming a Founding Member is free.') where campaign_slug = 'founding-cohort-1-wed-clicked' and step = 1;
update ve_outreach_campaign_emails set body = replace(body, 'Joining is free, a two-minute survey, and anyone who joins before midnight Eastern on January 1, 2027 is a Founding Member.', 'Becoming a Founding Member is free, open until midnight Eastern on January 1, 2027.') where campaign_slug = 'founding-cohort-1-wed-opened' and step = 1;
update ve_outreach_campaign_emails set body = replace(body, 'joining is free, a two-minute survey, and the Welcome Guide shows you around. Anyone who joins before midnight Eastern on January 1, 2027 is a Founding Member.', 'the Welcome Guide shows you around, and becoming a Founding Member is free, open until midnight Eastern on January 1, 2027.') where campaign_slug = 'founding-cohort-1-wed-quiet' and step = 1;
